def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'
    if n == 2:
        return 'C'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]

    # Counters
    opp_c = 0
    me_d = 0
    for a in opp:
        if a == 'C':
            opp_c += 1
    for a in me:
        if a == 'D':
            me_d += 1
    opp_d = n - opp_c

    # Track consecutive opponent defections at end
    opp_d_streak = 0
    for a in reversed(opp):
        if a == 'D':
            opp_d_streak += 1
        else:
            break

    # Track consecutive opponent cooperations at end
    opp_c_streak = 0
    for a in reversed(opp):
        if a == 'C':
            opp_c_streak += 1
        else:
            break

    # Endgame: defect in the very last rounds for guaranteed extra payoff
    remaining = 100 - n
    if remaining <= 3:
        return 'D'

    # Early game: establish cooperation but probe a bit
    if n < 8:
        return 'C'

    opp_rate = opp_d / float(n)

    # Detect persistent defector: defect heavily to avoid being farmed
    if opp_rate >= 0.6 and opp_d_streak >= 2:
        return 'D'

    # Long defection streak: punish hard, rarely forgive
    if opp_d_streak >= 4:
        return 'D'
    if opp_d_streak == 3:
        if rng.random() < 0.15:
            return 'C'
        return 'D'

    # Two defections in a row: retaliate, but with occasional forgiveness
    if opp_d_streak == 2:
        if rng.random() < 0.2:
            return 'C'
        return 'D'

    # Single defection
    if opp_d_streak == 1:
        # If opponent is generally cooperative, retaliate once then restore
        if opp_rate <= 0.25:
            if me_d == 0 or me[-1] == 'C':
                return 'D'
            return 'C'
        # Against moderately exploitative opponents, retaliate and probe
        if opp_rate <= 0.45:
            if me[-1] == 'D':
                if rng.random() < 0.5:
                    return 'C'
                return 'D'
            return 'D'
        # Hostile opponent: mostly defect
        if rng.random() < 0.7:
            return 'D'
        return 'C'

    # Opponent has been cooperating recently
    if opp_rate <= 0.1:
        # Very cooperative opponent: exploit occasionally but keep mutual C
        if opp_c_streak >= 3:
            # Small chance to defect for exploitation, but not too often
            if rng.random() < 0.08:
                return 'D'
            return 'C'
        return 'C'

    if opp_rate <= 0.3:
        # Moderately cooperative: cooperate, occasionally test
        if rng.random() < 0.06:
            return 'D'
        return 'C'

    if opp_rate <= 0.5:
        # Mixed opponent: cooperate cautiously, defect sometimes
        if rng.random() < 0.2:
            return 'D'
        return 'C'

    # Opponent mostly defects: defect with high probability
    if rng.random() < 0.85:
        return 'D'
    return 'C'
